                RECEIVER_BYTES,
                "factored weighted closure receiving view"
            )
            .is_err());
        budget.remaining = usize::MAX;
        assert!(receive(&function, Rc::clone(&map), &mut budget).is_err());
    });
    assert!(refused && first.is_some());
    assert_eq!(paid, 0);
    assert_eq!(Rc::strong_count(&map), 1);
}

