    CACHED_PRELUDE_ACQUIRED.with(|acquired| acquired.set(acquired.get() + 1));
}

#[cfg(test)]
pub(super) fn cached_prelude_acquisitions() -> usize {
    CACHED_PRELUDE_ACQUIRED.with(std::cell::Cell::get)
}

